solution.solution.c:
int seconds_in_days(int days)
{
    return days * 86400;
}

long long seconds_in_years(int years)
{
    return (long long)years * 365 * 86400;
}

unsigned char low_byte(int n)
{
    return (unsigned char)n;
}

int is_upper_letter(char c)
{
    return c >= 'A' && c <= 'Z';
}

unitTests:
TEST("seconds in days") { CHECK_EQ(seconds_in_days(1), 86400); CHECK_EQ(seconds_in_days(7), 604800); CHECK_EQ(seconds_in_days(0), 0); }
TEST("seconds in years needs long long") { CHECK_EQ(seconds_in_years(1), 31536000LL); CHECK_EQ(seconds_in_years(100), 3153600000LL); CHECK_EQ(seconds_in_years(1000), 31536000000LL); }
TEST("the low byte") { CHECK_EQ(low_byte(300), 44); CHECK_EQ(low_byte(255), 255); CHECK_EQ(low_byte(256), 0); CHECK_EQ(low_byte(-1), 255); }
TEST("upper-case letters") { CHECK(is_upper_letter('A')); CHECK(is_upper_letter('Z')); CHECK(!is_upper_letter('a')); CHECK(!is_upper_letter('5')); CHECK(!is_upper_letter('[')); }

